{
"type": "object",
"properties": {
"decision": {
"type": "string",
"enum": ["SAFE", "AMBIGUOUS", "BLOCK"],
"description": "Итоговое решение по промпту"
},
"category": {
"type": "string",
"description": "Категория нарушения или SAFE"
},
"risk_level": {
"type": "string",
"enum": ["LOW", "MEDIUM", "HIGH"],
"description": "Уровень риска блокировки"
},
"problem_fragments": {
"type": "string",
"description": "Фрагмент или фрагменты исходного промпта, вызвавшие проблему (одна строка; если несколько — через запятую). Если проблем нет — пустая строка."
},
"recommendation": {
"type": "string",
"description": "Пользовательская рекомендация по исправлению промпта. Если проблем нет — коротко: что по тексту всё допустимо."
}
},
"required": [
"decision",
"category",
"risk_level",
"problem_fragments",
"recommendation"
],
"additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "rewritten_prompt": {
      "type": "string",
      "description": "Переписанный пользовательский промпт, приведённый в соответствие с правилами и ограничениями. Одна строка, человеко-читаемая, без пояснений."
    },
    "status": {
      "type": "string",
      "enum": [
        "rewritten",
        "unchanged",
        "blocked"
      ],
      "description": "Статус обработки: rewritten — промпт был изменён; unchanged — промпт допустим и не изменялся; blocked — промпт невозможно привести в соответствие правилам."
    }
  },
  "required": [
    "rewritten_prompt",
    "status"
  ],
  "additionalProperties": false
}

