function escapeMarkdownV2(text) {
  if (typeof text !== 'string') return text;
  return text.replace(/([_*\[\]()~`>#+\-=|{}.!\\])/g, '\\$1');
}

// Берём входной item
const item = items[0];

// Путь к данным GPT (по твоему скрину)
const data = item.json.output[0].content[0].text;

// Экранируем ВСЕ значения
const escaped = {
  decision: escapeMarkdownV2(data.decision),
  category: escapeMarkdownV2(data.category),
  risk_level: escapeMarkdownV2(data.risk_level),
  problem_fragments: escapeMarkdownV2(data.problem_fragments),
  recommendation: escapeMarkdownV2(data.recommendation),
};

// Возвращаем массив items
return [
  {
    json: escaped
  }
];

function escapeMarkdownV2(text) {
  if (typeof text !== 'string') return text;
  return text.replace(/([_*\[\]()~`>#+\-=|{}.!\\])/g, '\\$1');
}

function escapeAllStrings(value) {
  if (typeof value === 'string') {
    return escapeMarkdownV2(value);
  }
  if (Array.isArray(value)) {
    return value.map(escapeAllStrings);
  }
  if (value !== null && typeof value === 'object') {
    const result = {};
    for (const key in value) {
      result[key] = escapeAllStrings(value[key]);
    }
    return result;
  }
  return value;
}

const escaped = escapeAllStrings(items[0].json);

return [
  {
    json: escaped,
  },
];

